private Node insert(Node n, int k) {          // returns the new subtree root
    if (n == null) return new Node(k);
    if (k < n.key) n.left = insert(n.left, k);
    else if (k > n.key) n.right = insert(n.right, k);
    return n;                                 // duplicate: no change
}
private boolean contains(Node n, int k) {
    if (n == null) return false;
    if (k == n.key) return true;
    return k < n.key ? contains(n.left, k) : contains(n.right, k);
}

private Node delete(Node n, int k) {
    if (n == null) return null;
    if (k < n.key) n.left = delete(n.left, k);
    else if (k > n.key) n.right = delete(n.right, k);
    else {
        if (n.left == null) return n.right;
        if (n.right == null) return n.left;
        Node s = n.right;
        while (s.left != null) s = s.left;    // successor
        n.key = s.key;
        n.right = delete(n.right, s.key);
    }
    return n;
}

Node rotateLeft(Node h) {        // h's right child x becomes the subtree root
    Node x = h.right;
    h.right = x.left;            // x's old left subtree switches parents
    x.left = h;
    x.color = h.color;
    h.color = RED;
    return x;
}
Node rotateRight(Node h) {       // mirror image
    Node x = h.left;
    h.left = x.right;
    x.right = h;
    x.color = h.color;
    h.color = RED;
    return x;
}

Node put(Node h, int k) {
    if (h == null) return new Node(k, RED);
    if (k < h.key) h.left = put(h.left, k);
    else if (k > h.key) h.right = put(h.right, k);
    if (isRed(h.right) && !isRed(h.left))     h = rotateLeft(h);
    if (isRed(h.left) && isRed(h.left.left))  h = rotateRight(h);
    if (isRed(h.left) && isRed(h.right))      flipColors(h);
    return h;
}

