// returns bh(x); sets colors in x's subtree
static int restore(Node x) {
    if (x == null) return 0;
    int me = 1 + restore(x.right);        // rightmost path length
    int l = restore(x.left);
    x.color = BLACK;                      // parent decides x's color
    if (x.left != null) x.left.color = (l == me) ? RED : BLACK;
    return me;
}

static Node convert(TNode t) {
    if (t == null) return null;
    boolean leaf = (t.kids == null);
    if (t.keys.length == 1) {
        Node x = new Node(t.keys[0], BLACK);
        if (!leaf) { x.left = convert(t.kids[0]); x.right = convert(t.kids[1]); }
        return x;
    }
    Node b = new Node(t.keys[1], BLACK);
    Node a = new Node(t.keys[0], RED);
    b.left = a;
    if (!leaf) {
        a.left = convert(t.kids[0]);     // keys < a
        a.right = convert(t.kids[1]);    // a < keys < b
        b.right = convert(t.kids[2]);    // keys > b
    }
    return b;
}

static Integer ceiling(Node n, int k) {
    Integer best = null;
    while (n != null) {
        if (n.key == k) return k;
        if (n.key > k) { best = n.key; n = n.left; }   // candidate; look for smaller
        else n = n.right;                              // too small; go right
    }
    return best;
}

static int countRange(Node n, int lo, int hi) {
    if (n == null) return 0;
    if (n.key < lo) return countRange(n.right, lo, hi);   // whole left side too small
    if (n.key > hi) return countRange(n.left, lo, hi);    // whole right side too big
    return 1 + countRange(n.left, lo, hi) + countRange(n.right, lo, hi);
}
